    void shouldNotRefundNonRefundablePlan() {
        Reservation reservation = new Reservation(
            1, "101", "João", "joao@example.com", "12345678900",
            LocalDate.of(2027, 3, 10),
            LocalDate.of(2027, 3, 12),
