    void shouldIdentifyHighSeasonInDecember() {
        Reservation reservation = new Reservation(
            1, "101", "João", "joao@example.com", "12345678900",
            LocalDate.of(2027, 12, 15),
            LocalDate.of(2027, 12, 16),
